  ('cuidado-facial', 'Cuidado facial', 'Limpieza y preparación de la piel.', 5),
  ('talcos', 'Talcos', 'Acabados profesionales para barbería.', 6),
  ('accesorios', 'Accesorios', 'Complementos para el servicio profesional.', 7)
