insert into public.products (name, slug, description, short_description, category_id, brand_id, price, main_image_url, is_active, is_available) values
  ('After Shave MIDNIGHT', 'level3-after-shave-midnight', 'Fragancia MIDNIGHT con notas de limón, menta y verbena de la India. Ideal para finalizar el afeitado dejando una sensación fresca y perfumada.', 'Fragancia MIDNIGHT con notas de limón, menta y verbena de la India. Ideal para finalizar el afeitado dejando una sensación fresca y perfumada.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-midnight.webp', true, true),
  ('After Shave FRESH', 'level3-after-shave-fresh', 'Fragancia FRESH con notas de bergamota de Calabria y pimienta. Ayuda a calmar la piel después del afeitado y deja un aroma limpio y elegante.', 'Fragancia FRESH con notas de bergamota de Calabria y pimienta. Ayuda a calmar la piel después del afeitado y deja un aroma limpio y elegante.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-fresh.webp', true, true),
  ('After Shave FROST', 'level3-after-shave-frost', 'Fragancia FROST con notas de nuez moscada, vainilla, bayas de enebro y maderas ambaradas. Aporta frescura y una terminación aromática intensa.', 'Fragancia FROST con notas de nuez moscada, vainilla, bayas de enebro y maderas ambaradas. Aporta frescura y una terminación aromática intensa.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-frost.webp', true, true),
  ('After Shave ROYALE', 'level3-after-shave-royale', 'Fragancia ROYALE con notas de pomelo, jengibre, ambrox y cítricos. Ideal para completar el servicio de afeitado con un aroma moderno y sofisticado.', 'Fragancia ROYALE con notas de pomelo, jengibre, ambrox y cítricos. Ideal para completar el servicio de afeitado con un aroma moderno y sofisticado.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-royale.webp', true, true),
  ('After Shave AQUA', 'level3-after-shave-aqua', 'Fragancia AQUA con notas de pomelo, limón, menta y pimienta rosa. Brinda una sensación fresca y revitalizante después del afeitado.', 'Fragancia AQUA con notas de pomelo, limón, menta y pimienta rosa. Brinda una sensación fresca y revitalizante después del afeitado.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-aqua.webp', true, true),
  ('After Shave VIBRANT', 'level3-after-shave-vibrant', 'Fragancia VIBRANT con notas verdes, pomelo, especias, bergamota, lavanda y petitgrain. Deja la piel suave, fresca y agradablemente perfumada.', 'Fragancia VIBRANT con notas verdes, pomelo, especias, bergamota, lavanda y petitgrain. Deja la piel suave, fresca y agradablemente perfumada.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-vibrant.webp', true, true),
  ('After Shave ROSÉ', 'level3-after-shave-rose', 'Fragancia ROSÉ con notas de maracuyá, melocotón y frambuesa. Ofrece un aroma frutal y fresco para finalizar el afeitado.', 'Fragancia ROSÉ con notas de maracuyá, melocotón y frambuesa. Ofrece un aroma frutal y fresco para finalizar el afeitado.', (select id from categories where slug = 'after-shave'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-after-shave-rose.webp', true, true),
  ('Shaving Gel AQUA', 'level3-shaving-gel-aqua', 'Su fórmula permite ver claramente la zona de trabajo, lubrica e hidrata la piel y ayuda a reducir la irritación y los pequeños cortes. Fragancia AQUA.', 'Su fórmula permite ver claramente la zona de trabajo, lubrica e hidrata la piel y ayuda a reducir la irritación y los pequeños cortes. Fragancia AQUA.', (select id from categories where slug = 'afeitado'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-shaving-gel-aqua.webp', true, true),
  ('Shaving Gel ICE', 'level3-shaving-gel-ice', 'Facilita el deslizamiento de la cuchilla, protege e hidrata la piel y permite delineados precisos al mantener visible la zona de afeitado. Fragancia ICE.', 'Facilita el deslizamiento de la cuchilla, protege e hidrata la piel y permite delineados precisos al mantener visible la zona de afeitado. Fragancia ICE.', (select id from categories where slug = 'afeitado'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-shaving-gel-ice.webp', true, true),
  ('Black Mask', 'level3-black-mask', 'Ayuda a retirar puntos negros, suciedad, células muertas y exceso de grasa. Limpia los poros y deja la piel más suave, limpia y fresca.', 'Ayuda a retirar puntos negros, suciedad, células muertas y exceso de grasa. Limpia los poros y deja la piel más suave, limpia y fresca.', (select id from categories where slug = 'cuidado-facial'), (select id from brands where slug = 'level3'), 90, '/catalogo/level3/level3-black-mask.webp', true, true),
  ('Pink Mask', 'level3-pink-mask', 'Ayuda a remover impurezas y puntos negros, absorbe el exceso de grasa y favorece una apariencia más limpia, equilibrada y luminosa.', 'Ayuda a remover impurezas y puntos negros, absorbe el exceso de grasa y favorece una apariencia más limpia, equilibrada y luminosa.', (select id from categories where slug = 'cuidado-facial'), (select id from brands where slug = 'level3'), 90, '/catalogo/level3/level3-pink-mask.webp', true, true),
  ('Shampoo 2en 1', 'level3-shampoo-2en-1', 'Ayuda a suavizar, controlar el frizz y mejorar el brillo y la manejabilidad del cabello. Apto para todo tipo de cabello y práctico para uso profesional o en casa.', 'Ayuda a suavizar, controlar el frizz y mejorar el brillo y la manejabilidad del cabello. Apto para todo tipo de cabello y práctico para uso profesional o en casa.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 120, '/catalogo/level3/level3-shampoo-2en-1.webp', true, true),
  ('Tinted Gel', 'level3-tinted-gel', 'Proporciona color negro de aspecto natural, fijación fuerte, volumen, textura y brillo. Fórmula a base de agua, sin escamas y fácil de retirar con el lavado.', 'Proporciona color negro de aspecto natural, fijación fuerte, volumen, textura y brillo. Fórmula a base de agua, sin escamas y fácil de retirar con el lavado.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-tinted-gel.webp', true, true),
  ('Styling powder', 'level3-styling-powder', 'Se aplica directamente en raíces o cabello seco para crear textura y elevar el cabello sin necesidad de productos pesados. Ideal para estilos con volumen y acabado natural.', 'Se aplica directamente en raíces o cabello seco para crear textura y elevar el cabello sin necesidad de productos pesados. Ideal para estilos con volumen y acabado natural.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 110, '/catalogo/level3/level3-styling-powder.webp', true, true),
  ('Pomade', 'level3-pomade', 'Ideal para peinados clásicos o pulidos. Permite moldear y dar definición al cabello, proporcionando fijación y un acabado brillante de apariencia profesional.', 'Ideal para peinados clásicos o pulidos. Permite moldear y dar definición al cabello, proporcionando fijación y un acabado brillante de apariencia profesional.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-pomade.webp', true, true),
  ('Forming Cream', 'level3-forming-cream', 'Aporta volumen y textura sin dejar el cabello rígido o pegajoso. Su consistencia ligera permite remodelar el peinado y funciona especialmente bien en cabello fino o delgado.', 'Aporta volumen y textura sin dejar el cabello rígido o pegajoso. Su consistencia ligera permite remodelar el peinado y funciona especialmente bien en cabello fino o delgado.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-forming-cream.webp', true, true),
  ('Paste', 'level3-paste', 'Aporta textura, definición y volumen sin brillo. Su fórmula a base de agua es fácil de aplicar, permite retocar el estilo y se enjuaga sin dejar residuos.', 'Aporta textura, definición y volumen sin brillo. Su fórmula a base de agua es fácil de aplicar, permite retocar el estilo y se enjuaga sin dejar residuos.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-paste.webp', true, true),
  ('Spider wax', 'level3-spider-wax', 'Su efecto fibroso facilita moldear estilos texturizados con control flexible. Ideal para marcar mechones, aportar estructura y crear acabados modernos.', 'Su efecto fibroso facilita moldear estilos texturizados con control flexible. Ideal para marcar mechones, aportar estructura y crear acabados modernos.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-spider-wax.webp', true, true),
  ('Brillant Cream', 'level3-brillant-cream', 'Ofrece fijación duradera con flexibilidad para remodelar el cabello. Su textura suave ayuda a mejorar la definición y el brillo sin dejar residuos visibles.', 'Ofrece fijación duradera con flexibilidad para remodelar el cabello. Su textura suave ayuda a mejorar la definición y el brillo sin dejar residuos visibles.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-brillant-cream.webp', true, true),
  ('Matte Putty', 'level3-matte-putty', 'Aporta volumen suave, textura ligera y control flexible. Mantiene el cabello manejable y permite ajustar el peinado durante el día sin sensación pegajosa ni brillo.', 'Aporta volumen suave, textura ligera y control flexible. Mantiene el cabello manejable y permite ajustar el peinado durante el día sin sensación pegajosa ni brillo.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 99, '/catalogo/level3/level3-matte-putty.webp', true, true),
  ('Hair Gel', 'level3-hair-gel', 'Aporta definición, volumen y control sin sensación grasosa. Fórmula a base de agua y sin escamas, fácil de lavar y adecuada para estilos estructurados.', 'Aporta definición, volumen y control sin sensación grasosa. Fórmula a base de agua y sin escamas, fácil de lavar y adecuada para estilos estructurados.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 75, '/catalogo/level3/level3-hair-gel.webp', true, true),
  ('Cream Gel', 'level3-cream-gel', 'Ayuda a nutrir y proteger el cabello mientras aporta volumen, definición y control. Fórmula a base de agua, sin escamas y adecuada para definir rizos o estilos con brillo natural.', 'Ayuda a nutrir y proteger el cabello mientras aporta volumen, definición y control. Fórmula a base de agua, sin escamas y adecuada para definir rizos o estilos con brillo natural.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'level3'), 75, '/catalogo/level3/level3-cream-gel.webp', true, true),
  ('Mud Scrub Mask', 'level3-mud-scrub-mask', 'Con arcilla de caolín y extracto de manzanilla. Ayuda a retirar suciedad, exceso de grasa, impurezas, células muertas y puntos negros, dejando la piel más limpia y luminosa.', 'Con arcilla de caolín y extracto de manzanilla. Ayuda a retirar suciedad, exceso de grasa, impurezas, células muertas y puntos negros, dejando la piel más limpia y luminosa.', (select id from categories where slug = 'cuidado-facial'), (select id from brands where slug = 'level3'), 120, '/catalogo/level3/level3-mud-scrub-mask.webp', true, true),
  ('Inmortal  Styling powder', 'immortal-inmortal-styling-powder', 'Ideal para crear textura, levantar la raíz y dar cuerpo al cabello sin aspecto húmedo. Se aplica en pequeñas cantidades sobre cabello seco y se moldea con los dedos.', 'Ideal para crear textura, levantar la raíz y dar cuerpo al cabello sin aspecto húmedo. Se aplica en pequeñas cantidades sobre cabello seco y se moldea con los dedos.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'immortal'), 105, '/catalogo/immortal/immortal-inmortal-styling-powder.webp', true, true),
  ('Inmortal Beard Care Srerum', 'immortal-inmortal-beard-care-srerum', 'Ayuda a mantener la barba más manejable y con aspecto cuidado, reduciendo la sensación de resequedad. Aplicar unas gotas y distribuir de raíz a puntas.', 'Ayuda a mantener la barba más manejable y con aspecto cuidado, reduciendo la sensación de resequedad. Aplicar unas gotas y distribuir de raíz a puntas.', (select id from categories where slug = 'productos-para-barba'), (select id from brands where slug = 'immortal'), 90, '/catalogo/immortal/immortal-inmortal-beard-care-srerum.webp', true, true),
  ('Inmortal Beard Pomade Wax', 'immortal-inmortal-beard-pomade-wax', 'Permite ordenar cabellos rebeldes, definir la forma y dar un acabado pulido sin necesidad de usar grandes cantidades. Trabajar entre las manos antes de aplicar.', 'Permite ordenar cabellos rebeldes, definir la forma y dar un acabado pulido sin necesidad de usar grandes cantidades. Trabajar entre las manos antes de aplicar.', (select id from categories where slug = 'productos-para-barba'), (select id from brands where slug = 'immortal'), 90, '/catalogo/immortal/immortal-inmortal-beard-pomade-wax.webp', true, true),
  ('Black Mask', 'immortal-black-mask', 'Ayuda a retirar impurezas, exceso de grasa y residuos superficiales, dejando una sensación de limpieza. Aplicar una capa uniforme evitando ojos, labios y zonas con vello.', 'Ayuda a retirar impurezas, exceso de grasa y residuos superficiales, dejando una sensación de limpieza. Aplicar una capa uniforme evitando ojos, labios y zonas con vello.', (select id from categories where slug = 'cuidado-facial'), (select id from brands where slug = 'immortal'), 85, '/catalogo/immortal/immortal-black-mask.webp', true, true),
  ('Shampoo Immortal INFUSE', 'immortal-shampoo-immortal-infuse', 'Limpia el cabello y el cuero cabelludo mientras ayuda a mantener suavidad y una apariencia fresca. Adecuado para el lavado habitual en barbería o en casa.', 'Limpia el cabello y el cuero cabelludo mientras ayuda a mantener suavidad y una apariencia fresca. Adecuado para el lavado habitual en barbería o en casa.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'immortal'), 95, '/catalogo/immortal/immortal-shampoo-immortal-infuse.webp', true, true),
  ('Shampoo Immortal Anti-Caspa', 'immortal-shampoo-immortal-anti-caspa', 'Limpia el cuero cabelludo y ayuda a controlar la acumulación visible de escamas y grasa. Usar con masaje suave y enjuagar completamente.', 'Limpia el cuero cabelludo y ayuda a controlar la acumulación visible de escamas y grasa. Usar con masaje suave y enjuagar completamente.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'immortal'), 95, '/catalogo/immortal/immortal-shampoo-immortal-anti-caspa.webp', true, true),
  ('Shampoo Immortal Anti-Caida de Cabello', 'immortal-shampoo-immortal-anti-caida-de-cabello', 'Proporciona limpieza del cabello y cuero cabelludo y está orientado a fortalecer la apariencia de la fibra capilar. Utilizar de acuerdo con las indicaciones del envase.', 'Proporciona limpieza del cabello y cuero cabelludo y está orientado a fortalecer la apariencia de la fibra capilar. Utilizar de acuerdo con las indicaciones del envase.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'immortal'), 95, '/catalogo/immortal/immortal-shampoo-immortal-anti-caida-de-cabello.webp', true, true),
  ('Shampoo Immortal 3 en 1', 'immortal-shampoo-immortal-3-en-1', 'Permite realizar la limpieza diaria en un solo producto, con enjuague fácil y sensación de frescura. Útil para casa, gimnasio o viaje.', 'Permite realizar la limpieza diaria en un solo producto, con enjuague fácil y sensación de frescura. Útil para casa, gimnasio o viaje.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'immortal'), 95, '/catalogo/immortal/immortal-shampoo-immortal-3-en-1.webp', true, true),
  ('Agiva 01 Orange', 'agiva-agiva-01-orange', 'Su textura facilita la distribución y el moldeado del cabello. Ideal para estilos pulidos que necesitan control y definición durante el día.', 'Su textura facilita la distribución y el moldeado del cabello. Ideal para estilos pulidos que necesitan control y definición durante el día.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-01-orange.webp', true, true),
  ('Agiva 02 Blue', 'agiva-agiva-02-blue', 'Permite dar forma, definir y mantener el peinado con un acabado brillante. Aplicar una pequeña cantidad sobre cabello seco o ligeramente húmedo.', 'Permite dar forma, definir y mantener el peinado con un acabado brillante. Aplicar una pequeña cantidad sobre cabello seco o ligeramente húmedo.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-02-blue.webp', true, true),
  ('Agiva 03 Green', 'agiva-agiva-03-green', 'Indicada para peinados naturales, texturizados o con volumen. Se trabaja fácilmente con los dedos y ayuda a mantener el estilo sin brillo marcado.', 'Indicada para peinados naturales, texturizados o con volumen. Se trabaja fácilmente con los dedos y ayuda a mantener el estilo sin brillo marcado.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-03-green.webp', true, true),
  ('Agiva 04 Yellow', 'agiva-agiva-04-yellow', 'Se distribuye con facilidad y permite moldear distintos estilos, desde peinados clásicos hasta acabados más modernos. Se retira con lavado.', 'Se distribuye con facilidad y permite moldear distintos estilos, desde peinados clásicos hasta acabados más modernos. Se retira con lavado.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-04-yellow.webp', true, true),
  ('Agiva 05 Red', 'agiva-agiva-05-red', 'Ayuda a mantener cabellos difíciles en su lugar y a crear peinados definidos y duraderos. Usar poca cantidad y distribuir uniformemente.', 'Ayuda a mantener cabellos difíciles en su lugar y a crear peinados definidos y duraderos. Usar poca cantidad y distribuir uniformemente.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-05-red.webp', true, true),
  ('Agiva 06  Cream Wax', 'agiva-agiva-06-cream-wax', 'Su consistencia permite repartir el producto de forma uniforme, definir mechones y retocar el peinado durante la aplicación.', 'Su consistencia permite repartir el producto de forma uniforme, definir mechones y retocar el peinado durante la aplicación.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-06-cream-wax.webp', true, true),
  ('Agiva 10 Grey (Tela de Araña)', 'agiva-agiva-10-grey-tela-de-arana', 'Al trabajarla entre las manos forma fibras que ayudan a repartir el producto, separar mechones y dar textura al peinado con un acabado moderno.', 'Al trabajarla entre las manos forma fibras que ayudan a repartir el producto, separar mechones y dar textura al peinado con un acabado moderno.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 55, '/catalogo/agiva/agiva-agiva-10-grey-tela-de-arana.webp', true, true),
  ('Agiva Styling Dust', 'agiva-agiva-styling-dust', 'Se aplica sobre cabello seco, especialmente en la raíz, para aumentar el cuerpo y facilitar el moldeado. Usar poco producto y añadir más si es necesario.', 'Se aplica sobre cabello seco, especialmente en la raíz, para aumentar el cuerpo y facilitar el moldeado. Usar poco producto y añadir más si es necesario.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = 'agiva'), 99, '/catalogo/agiva/agiva-agiva-styling-dust.webp', true, true),
  ('Shaving Gel', 'agiva-shaving-gel', 'Ayuda a lubricar e hidratar la piel durante el afeitado y permite ver el contorno mientras se trabaja. Aplicar una capa fina antes de pasar la navaja o rasuradora.', 'Ayuda a lubricar e hidratar la piel durante el afeitado y permite ver el contorno mientras se trabaja. Aplicar una capa fina antes de pasar la navaja o rasuradora.', (select id from categories where slug = 'afeitado'), (select id from brands where slug = 'agiva'), 89, '/catalogo/agiva/agiva-shaving-gel.webp', true, true),
  ('Cera Telaraña Aroma Chicle', '4x4-cera-telarana-aroma-chicle', 'Su textura fibrosa permite distribuir el producto entre los mechones y crear peinados definidos con movimiento. Ideal para acabados modernos y texturizados.', 'Su textura fibrosa permite distribuir el producto entre los mechones y crear peinados definidos con movimiento. Ideal para acabados modernos y texturizados.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = '4x4'), 60, '/catalogo/4x4/4x4-cera-telarana-aroma-chicle.webp', true, true),
  ('Cera Telaraña Aroma Banana', '4x4-cera-telarana-aroma-banana', 'Forma fibras al trabajarla con las manos, facilitando la definición de mechones y el control del peinado. Aplicar en pequeñas cantidades.', 'Forma fibras al trabajarla con las manos, facilitando la definición de mechones y el control del peinado. Aplicar en pequeñas cantidades.', (select id from categories where slug = 'productos-para-cabello'), (select id from brands where slug = '4x4'), 60, '/catalogo/4x4/4x4-cera-telarana-aroma-banana.webp', true, true),
